WITH remaining_keys AS (SELECT level FROM employees INTERSECT ALL SELECT level FROM employees WHERE LOWER(TRIM(email)) = 'david.lee@gmail.com'), reconciled AS (SELECT s.* FROM employees s JOIN remaining_keys k ON s.level = k.level) SELECT s.full_name, s.email, s.dept_id, s.manager_id, s.job_title, s.salary, s.hire_date, (SELECT AVG(t2.salary) FROM employees t2 WHERE t2.dept_id = s.dept_id) AS avg_employee_salary FROM reconciled s ORDER BY job_title ASC
